  test("claimed without corrections scenario 3", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-04-05");
    expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
    await ui.setSetting(pg_uma, "floor", "2.00");
    await ui.setSetting(pg_uma, "terms", "10");
    await ui.setSetting(pg_uma, "late-pct", "5.00");
    await ui.setSetting(pg_uma, "policy-date", "2026-03-15");
    await ui.setSetting(pg_uma, "cap", "2.00");
    await ui.setSetting(pg_uma, "proof-threshold", "3.00");
    expect(await ui.setRole(pg_uma, "wes", "viewer")).toBe(true);
    await ui.setSetting(pg_uma, "grace-days", "0");
    await ui.setSetting(pg_uma, "entry-date", "2026-03-01");
    await ui.setSetting(pg_uma, "proof-threshold-A", "4.00");
    expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "4.00", "note": "tpl"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "33.33"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50", "from": "2026-03-16"})).toBe(true);
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C", "terms": "20"}));
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B", "tags": "b, a"}));
    expect(await ui.addPool(pg_uma, "P1")).toBe(true);
    expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ben", "share": "50.00", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
    expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Cam", "share": "50.00"})).toBe(true);
    await ui.setToday(pg_uma, "2026-04-11");
    await ui.expectAuditView(pg_uma, "Ben", [
      `SNAPSHOT sheet=${sheet} by=uma name=Ben due-total=n/a`,
      `POOL_MEMBER_ADDED sheet=${sheet} by=uma pool=P1 name=Ben share=50.00 from=2026-03-01 to=2026-03-15`,
      `ROLLUP sheet=${sheet} by=uma person=Ben claimed=0.00 due-total=n/a overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ben grade=C terms=20`
    ]);
    const c_ben_0 = ui.must(await ui.claimFromTemplate(pg_uma, p_ben, "T1"));
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.merge(pg_vic, p_ben, "Cam")).toBe(true);
    const c_cam_0 = await ui.claimAt(pg_vic, p_cam, 0);
    const c_cam_1 = ui.must(await ui.addClaim(pg_vic, p_cam, {"amount": "3.33", "date": "2026-03-09", "note": "n", "ref": "R-2"}));
    expect(await ui.editInline(pg_vic, c_cam_0, "0.40")).toBe(true);
    expect(await ui.retire(pg_vic, p_cam, "2026-03-09")).toBe(true);
    await ui.showRetired(pg_vic, true);
    await ui.refresh(pg_vic);
    expect(await ui.setRate(pg_vic, {"grade": "C", "pct": "33.33", "from": "2026-03-01"})).toBe(true);
    const c_cam_2 = ui.must(await ui.addClaim(pg_vic, p_cam, {"amount": "10.25", "date": "2026-02-10", "note": "n", "tags": "a, B"}));
    expect(await ui.addClaim(pg_vic, p_cam, {"amount": "20.00", "date": "2026-03-28", "note": "n"})).toBeNull();
    expect(await ui.claimAction(pg_vic, c_cam_2, "open")).toBe(true);
    const c_cam_3 = ui.must(await ui.quickAdd(pg_vic, {"name": "Cam", "amount": "99.95"}, p_cam));
    expect(await ui.editClaim(pg_vic, c_cam_1, {"date": "2026-02-10"})).toBe(true);
    await ui.refresh(pg_vic);
    expect(await ui.transfer(pg_vic, p_cam, `${sheet}-t`)).toBe(false);
    await ui.refresh(pg_vic);
    expect(await ui.addComment(pg_vic, c_cam_3, "")).toBe(false);
    await ui.expectAuditView(pg_vic, "Cam", [
      `CLAIM_EDITED sheet=${sheet} by=vic person=Cam amount=3.33 date=2026-02-10`,
      `CLAIM_ADDED sheet=${sheet} by=vic person=Cam amount=99.95 date=2026-03-01`,
      `CLAIM_OPENED sheet=${sheet} by=vic person=Cam amount=10.25 date=2026-02-10 number=FY2026-1`,
      `CLAIM_ADDED sheet=${sheet} by=vic person=Cam amount=10.25 date=2026-02-10 tags=a,b`,
      `PERSON_RETIRED sheet=${sheet} by=vic name=Cam from=2026-03-09`,
      `CLAIM_EDITED sheet=${sheet} by=vic person=Cam amount=0.40 date=2026-03-01`,
      `CLAIM_ADDED sheet=${sheet} by=vic person=Cam amount=3.33 date=2026-03-09 ref=R-2`,
      `SNAPSHOT sheet=${sheet} by=uma name=Cam due-total=0.00`,
      `POOL_MEMBER_ADDED sheet=${sheet} by=uma pool=P1 name=Cam share=50.00`,
      `ROLLUP sheet=${sheet} by=uma person=Cam claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Cam grade=B`
    ]);
    const pg_wes = await ui.userPage(browser, "wes", sheet);
    await ui.showRetired(pg_wes, true);
    expect(await ui.claimAction(pg_wes, c_cam_2, "settle")).toBe(false);
    expect(await ui.claimAction(pg_wes, c_cam_0, "open")).toBe(false);
    await ui.refresh(pg_wes);
